import lombok.Getter;
import lombok.Setter;
import org.slf4j.Logger;

@Getter
@Setter
public class AbstractDao {
    protected void throwServiceException(Logger logger, String opName) throws ServiceException {
        logger.error("Operation name: {}, Error code: {}, related service: {}",
            opName, "Operate DB Failed", "DataSmartCubeService");
        throw new ServiceException(String.format(
            "操作失败: %s, 错误代码: %s, 相关服务: %s",
            opName, "Operate DB Failed", "DataSmartCubeService"));
    }

    public <T> T getMapper(Class<T> type) {
        DBContext.setActiveDb(DBConstant.DB_NAME);
        return ContextUtil.getBean(type);
    }
}
