@Component
public class MaterialLibrariesDao extends AbstractDao {
    private static final Logger LOGGER = LoggerFactory.getLogger(MaterialLibrariesDao.class);

    public void insert(List<MaterialLibrariesPO> materialLibrariesPOList) throws ServiceException {
        if (CollectionUtils.isEmpty(materialLibrariesPOList)) {
            return;
        }
        try {
            MaterialLibrariesMapper mapper = getMapper(MaterialLibrariesMapper.class);
            mapper.insert(materialLibrariesPOList);
        } catch (Exception e) {
            LOGGER.error("insert failed. {}", e.getMessage());
            throwServiceException(LOGGER, "insert material");
        }
    }
}
